// Search box for the online manual. The pages work without this script; it only adds the results.
// search.json sits next to the pages and is generated by scripts/build-manual.mjs.
(() => {
  const fold = (s) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
  const words = (q) => [...new Set(fold(q).split(/[^\p{L}\p{N}]+/u).filter(Boolean))];
  let index = null;

  const load = () => {
    if (!index) {
      index = fetch("search.json")
        .then((r) => r.json())
        .then((topics) =>
          topics.map((t) => ({ ...t, fTitle: fold(t.title), fKeywords: fold(t.keywords), fText: fold(t.text) })),
        );
    }
    return index;
  };

  const count = (hay, needle) => {
    let n = 0;
    for (let i = hay.indexOf(needle); i >= 0 && n < 5; i = hay.indexOf(needle, i + needle.length)) n += 1;
    return n;
  };

  const snippet = (t, ws) => {
    let first = -1;
    for (const w of ws) {
      const i = t.fText.indexOf(w);
      if (i >= 0 && (first < 0 || i < first)) first = i;
    }
    const start = Math.max(0, first - 50);
    const end = Math.min(t.text.length, start + 140);
    return `${start > 0 ? "…" : ""}${t.text.slice(start, end).trim()}${end < t.text.length ? "…" : ""}`;
  };

  // Same ranking as the app's Help search: every word must appear; title beats keywords beats text.
  const search = (topics, q) => {
    const ws = words(q);
    if (!ws.length) return [];
    const out = [];
    topics.forEach((t, order) => {
      let score = 0;
      for (const w of ws) {
        const title = count(t.fTitle, w);
        const kw = count(t.fKeywords, w);
        const body = count(t.fText, w);
        if (!title && !kw && !body) return;
        score += title ? 100 + title * 10 : kw ? 40 + kw * 5 : 10 + body;
        score += kw * 2 + body;
      }
      out.push({ t, score, order, snip: snippet(t, ws) });
    });
    return out.sort((a, b) => b.score - a.score || a.order - b.order).slice(0, 12);
  };

  const el = (tag, text) => {
    const e = document.createElement(tag);
    if (text) e.textContent = text;
    return e;
  };

  document.querySelectorAll(".manual-search").forEach((box) => {
    const input = box.querySelector("input");
    const list = box.querySelector(".manual-results");
    let seq = 0;

    const render = async () => {
      const q = input.value.trim();
      const mine = ++seq;
      if (!q) {
        list.hidden = true;
        list.replaceChildren();
        return;
      }
      const results = search(await load(), q);
      if (mine !== seq) return;
      const items = results.map(({ t, snip }) => {
        const li = el("li");
        const a = el("a");
        a.href = `${t.id}.html`;
        a.append(el("strong", t.title), el("span", snip));
        li.append(a);
        return li;
      });
      if (!items.length) {
        const li = el("li", box.dataset.noResults);
        li.className = "empty";
        items.push(li);
      }
      list.replaceChildren(...items);
      list.hidden = false;
    };

    input.addEventListener("focus", load, { once: true });
    input.addEventListener("input", render);
    input.addEventListener("keydown", (e) => {
      const links = [...list.querySelectorAll("a")];
      if (e.key === "Enter" && links[0]) {
        e.preventDefault();
        location.href = links[0].href;
      } else if (e.key === "ArrowDown" && links[0]) {
        e.preventDefault();
        links[0].focus();
      } else if (e.key === "Escape") {
        input.value = "";
        render();
      }
    });
    list.addEventListener("keydown", (e) => {
      const links = [...list.querySelectorAll("a")];
      const i = links.indexOf(document.activeElement);
      if (e.key === "ArrowDown" && i < links.length - 1) {
        e.preventDefault();
        links[i + 1].focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        (i > 0 ? links[i - 1] : input).focus();
      } else if (e.key === "Escape") {
        input.focus();
      }
    });
  });
})();
